                grid[r+1][c] == 2 and grid[r][c-1] == 2 and
                grid[r][c+1] == 2):
                plus.add((r, c))
                arms.update({(r-1,c), (r+1,c), (r,c-1), (r,c+1)})

    # Exposed endpoints and the direction in which each points.
    endpoints = []
    for r, c in arms:
        for dr, dc in ((-1,0), (1,0), (0,-1), (0,1)):
            # Plus endpoints point outward from their center.
            if ((r+dr, c+dc) in plus):
                endpoints.append((r, c, dr, dc))
                break
        else:
            # Find the center whose arm this is, to get its outward direction.
            for pr, pc in plus:
                if abs(pr-r) + abs(pc-c) == 1:
                    endpoints.append((r, c, r-pr, c-pc))
                    break

    # Standalone 2 cells can connect in any direction.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r,c) not in arms:
                for dr, dc in ((-1,0), (1,0), (0,-1), (0,1)):
                    endpoints.append((r,c,dr,dc))

    for i, (r, c, dr, dc) in enumerate(endpoints):
        for s, t, er, ec in endpoints[i+1:]:
            if (dr, dc) != (-er, -ec):
                continue
            if dr and t != c:
                continue
            if dc and s != r:
                continue
